INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66041226', 66041226, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Tabung Oksigen 1 meterkubik', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 12968231000, 'April 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 0, '7606 units', '1. Pengiriman 7.606 unit Tabung Oksigen 1 Meter kubik ke 4.183 Puskesmas wilayah Indonesia terdiri dari : - Regional Barat (3.276 unit) dengan lokus 1.909 Puskesmas dan wilayah meliputi provinsi Aceh, Banten, Bengkulu, Jambi, Jawa Barat, Jawa Tengah, Kepulauan Bangka Belitung, Kepulauan Riau, Lampung, Riau, Sumatera Barat, Sumatera Selatan dan Sumatera Utara. - Regional Timur (4.330 unit) dengan lokus 2.274 Puskesmas dan wilayah meliputi provinsi Bali, DIY, Gorontalo, Jawa Timur, Kalimantan Barat, Kalimantan Selatan, Kalimantan Tengah, Kalimantan Timur, Kalimantan Utara, Maluku, Maluku Utara, Nusa Tenggara Barat, Nusa Tenggara Timur, Papua, Papua Barat, Papua Barat Daya, Papua Pegunungan, Papua Selatan, Papua Tengah, Sulawesi Barat, Sulawesi Selatan, Sulawesi Tengah, Sulawesi Tenggara, Sulawesi Utara. 2. Melakukan instalasi, uji fungsi dan pelatihan penggunaan alat di Puskesmas 3. Melakukan pengiriman, uji fungsi dan pelatihan penggunaan alat ke Puskesmas secara bertahap serta melakukan pemeliharaan selama minimal 2 (dua) tahun sejak alat terpasang.', 'A container designed to store and transport medical-grade oxygen. These tanks are commonly used in healthcare settings to provide supplemental oxygen to patients who have difficulty breathing or who require higher concentrations of oxygen due to medical conditions. A regulator is a device that attaches to the oxygen tank to control the flow of oxygen from the tank to the patient. It allows for precise adjustment of the oxygen flow rate, measured in liters per minute (LPM). Regulators ensure that the patient receives the correct amount of oxygen as prescribed by a healthcare provider. They typically have a gauge or dial that can be adjusted to set the desired flow rate.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 620757);
