INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62478320', 62478320, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Jasa Hygiene Service  TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 50000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1 Paket )', 'a. Merek Tidak ada penetapan perangkat dengan merek tertentu yang harus digunakan dalam pekerjaan hygiene service. b. Spesifikasi Fungsi/Kinerja Peralatan hygiene service dapat berfungsi dengan normal. Pengisian ulang detergen dapat dilakukan sesuai kebutuhan baik itu secara mandiri oleh Pusdiklat atau sesuai kunjungan penyedia. c. Tautan E-Purchasing Pengadaan dimaksud dapat dilakukan melalui E-Purchasing', 'No Nama Jumlah Satuan Pemeliharaan Jangka Waktu 1 Digital Sanitizer 39 Unit 1 kali/bulan 12 bulan 2 Foaming Hand Soap 12 Unit 12 liter/unit/tahun 12 bulan 4 Hand Dryer 9 Unit 1 kali/bulan 12 bulan 5 Sanitary Disposal 10 Unit 12 kali/tahun 12 bulan 7 Toilet Seat Cleaner 28 Unit 3 liter/unit/tahun 12 bulan Keterangan Teknis 1) Instalasi perangkat hygiene service diterima pada tanggal 2 Januari 2025; 2) Jangka waktu pelaksanaan pekerjaan selama 12 (dua belas) bulan; 3) Pengisian detergen hygiene service dapat dilakukan baik itu secara manual oleh penanggungjawab Pusdiklat APUPPT ataupun oleh Penyedia di saat kunjungan kerja; dan 4) Penggantian alat yang rusak saat pemakaian oleh Penyedia Barang dan Jasa. SPESIFIKASI PELAYANAN a. Tingkat pelayanan barang/jasa : 1) Layanan hygiene service dengan Spesifikasi Teknis yang ditetapkan; 2) Pemeliharaan barang dan isi ulang bahan hygiene service oleh Penyedia sesuai jadwal kunjungan. b. Pemeliharaan : Pemeliharaan dilaksanakan secara rutin berdasarkan kebutuhan penyedia terhadap perangkat hygiene service milik penyedia seperti penggantian sparepart yang menyebabkan kebocoran, isi ulang bahan hygiene service termasuk layanan pada saat terjadi kerusakan pada perangkat tersebut. SPESIFIKASI WAKTU a. Jangka waktu pelaksanaan pekerjaan : Selama 12 (dua belas) bulan sampai dengan 31 Desember 2026 b. Lokasi pelaksanaan pekerjaan : Pusdiklat APUPPT Jalan Raya Tapos Nomor 82, Cimpaeun, Tapos, Depok, Jawa Barat c. Informasi lainnya terkait waktu : Tanggal mulai pelaksanaan pekerjaan ditetapkan setelah pengadaan telah memasuki tahap penandatangan kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 622616);
