INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62550280', 62550280, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan LAN  Kantor Pusat BMKG', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lokasi', 'Perkembangan teknologi informasi saat ini telah terbukti mampu memberikan pengaruh positif bagi organisasi, baik dalam peningkatan efektivitas operasional maupun efisiensi biaya. Teknologi informasi yang dapat dikustomisasi sesuai kebutuhan pengguna memungkinkan otomatisasi proses kerja, mulai dari pengumpulan data, pengolahan data menjadi informasi, komunikasi internal, hingga penyampaian informasi kepada masyarakat. Dalam kondisi operasional, sistem jaringan Local Area Network (LAN) di lingkungan Gedung Kantor Pusat BMKG harus dipertahankan agar dapat bekerja selama 24 (dua puluh empat) jam sehari. Hal ini diperlukan untuk memastikan kegiatan pengumpulan data, proses pengolahan menjadi informasi, serta diseminasi informasi dapat berjalan optimal tanpa gangguan yang berdampak pada layanan internal maupun layanan publik BMKG.', 'Kegiatan Pemeliharaan Jaringan LAN Gedung Operasional dilaksanakan dengan menyediakan tenaga ahli teknis yang kompeten untuk melakukan monitoring, pemeliharaan, serta penanganan gangguan pada jaringan LAN di lingkungan Kantor Pusat BMKG. Layanan pemeliharaan ini harus memastikan performa jaringan tetap stabil dan andal, karena jaringan LAN merupakan infrastruktur pendukung utama operasional pengumpulan data, pengolahan informasi, dan diseminasi layanan BMKG. Oleh karena itu, sistem jaringan LAN wajib dipertahankan dalam kondisi beroperasi secara berkesinambungan selama 24 (dua puluh empat) jam sehari dan 7 (tujuh) hari seminggu (24x7), dengan pendekatan pemantauan proaktif dan respons gangguan yang cepat agar tidak mengganggu kelangsungan layanan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 624026);
