INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62478697', 62478697, 'analyze_legacy', 'Kementerian Perindustrian', 'central', 'Politeknik Teknologi Kimia Industri Medan', 'Security Outsorcing PTKI Medan TA. 2026', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Utara, Medan (Kota)', 790838000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Satuan Pengamanan atau sering juga disingkat Satpam adalah satuan kelompok petugas yang dibentuk oleh instansi/proyek/badan usaha untuk melakukan keamanan fisik (physical security) dalam rangka penyelenggaraan keamanan swakarsa di lingkungan kerjanya. Definisi lain menyebut satuan keamanan atau security guard adalah tim atau kelompok yang bertugas mengamankan aset dari tindakan kejahatan atau kerusakan. Fungsi Satuan Pengamanan (Security Guard) Di Kampus PTKI Medan Melindungi dan mengayomi lingkungan /tempat kerjanya yaitu Kampus PTKI Medan dari setiap gangguan keamanan, serta menegakkan peraturan dan tata tertib yang berlaku di lingkungan Kampus PTKI Medan.', 'Tenaga ahli yang dibutuhkan a. Komandan Regu - Jumlah 1 orang - Usia Maksimal 40 tahun - Memiliki sertifikat Gada Pratama dan KTA (melampirkan scan bukti sertifikat) - Memiliki Surat Keterangan Bebas Narkoba dari BNN - Memiliki SKCK yang masih berlaku b. Petugas - Jumlah 17 orang - Usia antara 20-40 tahun - Memiliki sertifikat Gada Pratama dan KTA (melampirkan scan bukti sertifikat) - Memiliki Surat Keterangan Bebas Narkoba dari BNN - Memiliki SKCK yang masih berlaku 2. Peralatan Kerja Memiliki kemampuan menyediakan peralatan/perlengkapan untuk melaksanakan pekerjaan jasa pengamanan ini : - Lampu Senter - Tonfa/Pentungan - Jas hujan - Sepatu PDL - Borgol 3. Jam Kerja : a. Masuk Pagi Jam 08.00 WIB s/d 20.00 WIB b. Masuk Malam Jam 20.00 WIB s/d 08.00 WIB 4. Persyaratan Badan Usaha : a. SIUP yang telah terintegrasi secara elektronik (OSS) b. Izin Operasional sebagai perusahaan penyedia jasa pekerja/buruh dari OSS c. Izin Badan Usaha Jasa Penyedia Jasa Keamanan dari MABES POLRI d. Memiliki NIB yang masih berlaku e. Memiliki NPWP dan telah memenuhi kewajiban perpajakan SPT Tahunan f. Memiliki sertifikat BPJS Ketenagakerjaan dan Kesehatan g. Memiliki Tanda pendaftaran wajib lapor ketenagakerjaan dari Dinas Tenaga Kerja h. Memiliki sertifikat dari Asosiasi Badan Usaha Jasa Pengamanan Indonesia (ABUJAPI) i. Direktur Perusahaan mempunyai Sertifikat Gada Utama j. Nomor KLBI 80100 (Aktivitas Keamanan Swasta)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 624324);
