INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62550206', 62550206, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa Komunikasi FO Seismik', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 615384000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'layanan ini adalah untuk memastikan pengiriman data observasi seismik dan telemetri secara real-time, berkelanjutan, dan aman, guna mendukung operasional Indonesia Tsunami Early Warning System (InaTEWS) serta sistem pemantauan kegempaan nasional. Karena karakteristik sistem TEWS yang menuntut kecepatan respon tinggi, maka layanan komunikasi harus memiliki latensi sangat rendah, SLA (Service Level Agreement) tinggi, serta jaminan kualitas bandwidth dedicated 1:1 untuk menjamin kestabilan pengiriman data dan menghindari penundaan transmisi yang dapat mempengaruhi waktu peringatan dini.', 'Seluruh proses penyediaan dan pengelolaan layanan sewa fiber optik harus dilaksanakan dengan SLA minimal 99.5% per bulan, menjamin latensi rendah, serta memastikan ketersediaan bandwidth dedicated 1:1 (non-sharing) agar seluruh data observasi dan telemetri dapat dikirimkan secara real-time ke pusat data BMKG tanpa gangguan. Layanan ini wajib mendukung transmisi data dua arah (upstream dan downstream) dengan performa stabil, packet loss maksimal 1%, jitter di bawah 50 ms, serta throughput penuh sesuai kapasitas kontraktual.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 625273);
