INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62479092', 62479092, 'analyze_legacy', 'Kab. Blitar', 'kabkota', 'Dinas Komunikasi, Informatika, Statistik dan Persandian', 'Belanja Pemeliharaan Komputer-Komputer Unit-Komputer Jaringan ( Pemeliharaan jaringan internet terintegrasi )', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Blitar (Kab.)', 222444000, 'December 2025', 'APBD', 0, 1, '12 bulan', 'Pengadaan Jasa Pemeliharaan Jaringan Internet Terintegrasi selama 12 bulan', 'Spesifikasi Mutu/Kualitas : Pekerjaan meliputi pemeliharaan jaringan intra Pemerintah Kabupaten Blitar yang terdiri dari: a. Pemeliharaan Preventif Kabel Fiber Optik • Inspeksi fisik jaringan Fiber Optik (FO) meliputi kabel, tiang, ODF/FTB/Peralatan GPON. • Pembersihan konektor dan terminasi FO. • Pengukuran kualitas jaringan menggunakan OTDR dan power meter. • Penataan dan pelabelan kabel. • Penggantian komponen minor bila diperlukan. • Dokumentasi hasil pemeliharaan. b. Pemeliharaan Korektif Kabel Fiber Optik • Penanganan gangguan jaringan FO (putus, redaman tinggi, degradasi layanan). • Penanganan kerusakan perangkat pada ODF/FTB/Peralatan GPON • Pelacakan lokasi gangguan menggunakan OTDR. • Perbaikan kabel FO (fusion splicing dan/atau penggantian segmen). • Pengujian ulang pasca perbaikan hingga layanan normal. • Penyusunan laporan gangguan dan penyebabnya. • Bekerja sama dengan penyedia internet untuk pemeliharaan jaringan fiber optik intra pemerintah c. SLA Pemeliharaan Preventif • Inspeksi fisik jaringan FO minimal 1 kali per bulan • Pengukuran kualitas FO (OTDR/power meter) minimal 1 kali per triwulan • Pembersihan ODF dan konektor FO dilakukan berkala • Preventive maintenance tidak dihitung sebagai downtime (jika terjadwal) d. SLA Pemeliharaan Korektif • Gangguan wajib ditangani on-call 24/7 • Perbaikan disarankan menggunakan fusion splicing • Setelah perbaikan, wajib dilakukan: o Pengujian OTDR o Pengujian layanan • Hasil pengujian dilampirkan dalam laporan e. Ready For Services dalam 3 hari Spesfikasi Penunjang : Pemeliharaan Jaringan Internet dan NOC: • Monitoring jaringan secara berkelanjutan melalui Network Operation Center (NOC). • Memiliki keahlian dalam konfigurasi dan optimalisasi Border Gateway Protocol (BGP), Open Shortest Path First (OSPF), dan Virtual LAN (VLAN). • Penanganan dan eskalasi gangguan jaringan. • Monitoring utilisasi bandwidth, latency, dan availability. • Pengelolaan ticketing gangguan. • Penyusunan laporan kinerja jaringan. Personel, Penyedia wajib menyediakan tenaga teknis yang kompeten, terdiri dari: • Teknisi Fiber Optik. • Engineer jaringan / NOC. • Penanggung jawab teknis pekerjaan. Menyediakan Engineer on site (EOS), minimal 1 orang untuk Teknisi Fiber Optik dan minimal 1 orang untuk Engineer jaringan / NOC. Peralatan Kerja, Penyedia wajib memiliki peralatan pendukung minimal: • OTDR single mode. • Fusion splicer. • Optical power meter dan light source. • Peralatan pendukung pemeliharaan FO. • Sistem monitoring jaringan (NMS). Pelaporan, Penyedia wajib menyampaikan: • Laporan pemeliharaan preventif bulanan. • Laporan gangguan dan perbaikan. • Hasil pengukuran OTDR. • Laporan pencapaian SLA bulanan. Ketentuan Lain: • Seluruh pekerjaan dilaksanakan sesuai standar keselamatan kerja. • Penyedia bertanggung jawab atas kualitas pekerjaan. • Penyedia wajib menjaga keamanan dan kerahasiaan jaringan. Spesifikasi Pelayanan : Tingkat pelayanan barang/jasa: 1. Harga sudah termasuk PPN 11% 2. Kontrak 1 Tahun 3. Tarif sudah termasuk instalasi 4. After Sales Service: • Complaint by WA (Fast Response) • Customer Assistance Representative • Preventive and Corrective Maintenance • Layanan On Site • Portal monitoring real-time (traffic, link quality, status) • NOC 24/7 untuk dukungan teknis • Sistem tiket untuk downtime & gangguan • Alert otomatis via email/WhatsApp (opsional) Pelatihan dan Bantuan Teknis dari Penyedia Barang/Jasa : Ada Pemeliharaan Aspek pemeliharaan dan perbaikan harus dinyatakan dalam ruang lingkup spesifikasi : Garansi akan diberikan oleh penyedia terhadap kerusakan yang tidak diakibatkan oleh kelalaian pengguna, bencana alam, atau modifikasi yang tidak diizinkan Informasi lainnya terkait spesifikasi pelayanan : Harga sudah termasuk pajak, biaya pengiriman, biaya instalasi, biaya pelatihan dan garansi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 625706);
